import { SITE } from '@/config/site'

// RFC 9728 §3.1: metadata for a resource at https://host/<path> lives at
// /.well-known/oauth-protected-resource/<path> (rewritten here in next.config.mjs). Every page is
// public, so each answer mirrors the root file generated by scripts/gen-agent-files.mjs, with the
// page's own URL as the resource identifier.
export async function GET(request, { params }) {
  const { path = [] } = await params
  const resource = `${SITE.url}/${path.join('/')}${path.length ? '/' : ''}`
  return Response.json(
    {
      resource,
      resource_name: `${SITE.name} public catalogue`,
      authorization_servers: [],
      scopes_supported: [],
      bearer_methods_supported: [],
      resource_documentation: `${SITE.url}/auth.md`,
      resource_policy_uri: `${SITE.url}/terms/`,
      tls_client_certificate_bound_access_tokens: false,
      note: 'All public catalogue resources are accessible without OAuth tokens.',
    },
    { headers: { 'Access-Control-Allow-Origin': '*', 'Cache-Control': 'public, max-age=3600' } }
  )
}
